    M = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if circuit[i][j] == '1':
                M[i][j] = Fraction(1, 2**i * 2**j)
    return matrix_power(M, n)

